Serie *retorna_preenchido(int *indice_atual, Serie *vetor_base)
{
    // Abre o arquivo.
    FILE *arquivo = fopen("streaming_db.csv", "r");
    if (arquivo == NULL)
    {
        perror("\nErro ao abrir o arquivo!\n");
        exit(1);
    }

    // Variáveis de trabalho
