        serie = (Serie *)realloc(serie, (contador + 1) * sizeof(Serie));
        if (serie == NULL) {
             perror("Erro ao realocar memória para as séries");
             break;
        }

        // Inicializa a série atual (serie[contador])
        Serie *serie_atual = &serie[contador];

        // --- PARSING CSV ---
        pt = strtok(vetor_guarda_linha, ",");
        serie_atual->codigo = atoi(pt);

        pt = strtok(NULL, ",");
        strcpy(serie_atual->titulo, pt);

        pt = strtok(NULL, ",");
        strcpy(serie_atual->genero, pt);

        pt = strtok(NULL, ",");
        serie_atual->classificacao = atoi(pt);

        pt = strtok(NULL, ",");
        strcpy(serie_atual->plataforma, pt);

        pt = strtok(NULL, ",");
        serie_atual->duracao_media = atoi(pt);

        pt = strtok(NULL, ",");
        serie_atual->quantidade_de_temporada = atoi(pt);

        // Aloca memória para o array de episódios
        serie_atual->quantidade_de_ep = (int *)malloc(serie_atual->quantidade_de_temporada * sizeof(int));
        if (serie_atual->quantidade_de_ep == NULL) {
             perror("Erro ao alocar memória para episódios");
             break;
        }

        // Lê os episódios (separados por ", ")
        for (int j = 0; j < serie_atual->quantidade_de_temporada; j++)
        {
            // ATENÇÃO: Seu delimitador aqui é ", ", o que é diferente do ", " da linha anterior.
            // Se a leitura for consistente no arquivo, isso deve funcionar.
            pt = strtok(NULL, ", ");
            serie_atual->quantidade_de_ep[j] = atoi(pt);
        }

        contador++;
    }

    fclose(arquivo);

    // Se a lógica for estritamente usar *indice_atual, você ajustaria aqui.
    // Se o objetivo é retornar o vetor completo, retornamos 'serie'.
    return serie;
}
