    size_t result = ZSTD_compress(
        compressed_buffer.data(), // Buffer de destino
        compressed_size,          // Tamanho máximo do buffer de destino
        input_data,               // Dados de entrada
        input_size,               // Tamanho dos dados de entrada
        level                      // Nível de compressão
    );

