int Zlib::NormalUncompress(uint8_t* dest, uint32_t* destLen, const uint8_t* source, uint32_t sourceLen) {
    if (sourceLen == 0) {
        return -1;
    }    z_stream strm;

    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = sourceLen;
    strm.next_in = (Bytef*)source;
    strm.avail_out = *destLen;
    strm.next_out = dest;
    int ret = inflateInit(&strm);
    if (ret != Z_OK) {
        return -1;
    }

    ret = inflate(&strm, Z_FINISH);

    if (ret != Z_OK && ret != Z_STREAM_END) {
        inflateEnd(&strm);
        return -1;
    }

    *destLen = strm.total_out;
    inflateEnd(&strm);
    return 0;

}
